<template><BioNexusStateDialog ref="stateDialog" :saving="saving" @confirm="row=>emit('confirm',row)" /></template>
<script setup>import{ref}from'vue';import BioNexusStateDialog from'@/components/ui/BioNexusStateDialog.vue';defineProps({saving:Boolean});const emit=defineEmits(['confirm']),stateDialog=ref(null);const options={activateTitle:'Activar laboratorio',deactivateTitle:'Inactivar laboratorio',activateMessage:'El laboratorio volvera a estar disponible para nuevas asociaciones.',deactivateMessage:'El laboratorio permanecera visible, pero no admitira nuevas asociaciones.',label:r=>r?.description||'Laboratorio de referencia'};function open(row){stateDialog.value?.open(row,options)}function close(){stateDialog.value?.close()}function clearError(){stateDialog.value?.clearError()}function setError(v){stateDialog.value?.setError(v)}defineExpose({open,close,clearError,setError})</script>
